from pathlib import Path

path = Path(r"frontend/lib/features/admin/presentation/screens/rama_externa/rama_externa_screen.dart")
text = path.read_text(encoding="utf-8")
old = """  // Helper para formatear hora del evento (UTC ��' local Chile)\n  String _formatEventTimeLocal(Map<String, dynamic> e) {\n    // Lee fecha + horas posibles\n    final fechaStr = (e['fecha'] ?? e['fechaEvento'] ?? '').toString();\n    final hIni = (e['horaInicio'] ?? e['hora'] ?? e['hora_evento'])?.toString();\n    final hFin = (e['horaFin'])?.toString();\n\n    // Si no hay fecha u hora, no hay nada que mostrar\n    if (fechaStr.isEmpty || (hIni == null && hFin == null)) return '';\n\n    // Helper local para parsear \"YYYY-MM-DD\" + \"HH:mm\" como UTC y llevar a local\n    DateTime? utcToLocal(String date, String time) {\n      try {\n        // Construye un ISO completo en UTC y pǭsalo a local\n        final iso = '${date}T$time:00Z';\n        return DateTime.parse(iso).toLocal();\n      } catch (_) {\n        // Si el backend ya da hora local, intenta parsear como local\n        try {\n          final parts = time.split(':');\n          final hh = int.parse(parts[0]);\n          final mm = int.parse(parts[1]);\n          final base = DateTime.parse(date); // local\n          return DateTime(base.year, base.month, base.day, hh, mm);\n        } catch (_) {\n          return null;\n        }\n      }\n    }\n\n    String fmt(DateTime dt) {\n      final two = (int n) => n.toString().padLeft(2, '0');\n      return '${two(dt.hour)}:${two(dt.minute)}';\n    }\n\n    final ini = hIni != null ? utcToLocal(fechaStr, hIni) : null;\n    final fin = hFin != null ? utcToLocal(fechaStr, hFin) : null;\n\n    if (ini != null && fin != null) return '${fmt(ini)} �?" ${fmt(fin)}';\n    if (ini != null) return fmt(ini);\n    if (fin != null) return fmt(fin);\n    return '';\n  }\n\n"""
new = """  // Helper para formatear hora del evento (UTC -> horario Chile)\n  String _formatEventTimeLocal(Map<String, dynamic> e) {\n    final fechaStr =\n        (e['fecha'] ?? e['fechaEvento'] ?? e['fecha_evento'] ?? '')\n            .toString()\n            .trim();\n    final hIniRaw =\n        (e['horaInicio'] ?? e['hora'] ?? e['hora_evento'])?.toString().trim();\n    final hFinRaw =\n        (e['horaFin'] ?? e['horaTermino'] ?? e['hora_fin'])\n            ?.toString()\n            .trim();\n\n    if (fechaStr.isEmpty || (hIniRaw == null && hFinRaw == null)) return '';\n\n    String extractDate(String raw) {\n      if (raw.isEmpty) return raw;\n      final parts = raw.split('T');\n      return parts.isNotEmpty && parts.first.isNotEmpty ? parts.first : raw;\n    }\n\n    String normaliseTime(String? raw) {\n      if (raw == null || raw.isEmpty) return '';\n      var value = raw.trim();\n      if (value.isEmpty) return '';\n      if (value.contains(' ')) {\n        value = value.split(' ').first;\n      }\n      if (value.endsWith('Z') || value.endsWith('z')) {\n        value = value.substring(0, value.length - 1);\n      }\n      if (value.contains('.')) {\n        value = value.split('.').first;\n      }\n      final offsetIndex = value.indexOf(RegExp(r'[+-]'), 1);\n      if (offsetIndex != -1) {\n        value = value.substring(0, offsetIndex);\n      }\n      final segments = value.split(':').where((segment) => segment.isNotEmpty).toList();\n      if (segments.isEmpty) return '';\n      final hh = segments[0].padLeft(2, '0');\n      final mm = (segments.length > 1 ? segments[1] : '00').padLeft(2, '0');\n      final ss = (segments.length > 2 ? segments[2] : '00').padLeft(2, '0');\n      return '$hh:$mm:$ss';\n    }\n\n    DateTime? parseUtcToLocal(String? raw) {\n      final normalized = normaliseTime(raw);\n      if (normalized.isEmpty) return null;\n      final baseDate = extractDate(fechaStr);\n      final candidates = <String>[\n        '${baseDate}T${normalized}Z',\n        '${baseDate}T$normalized',\n      ];\n\n      for (final candidate in candidates) {\n        try {\n          final parsed = DateTime.parse(candidate);\n          return parsed.toLocal();\n        } catch (_) {\n          continue;\n        }\n      }\n\n      try {\n        final backupDate = DateTime.parse(fechaStr);\n        final hour = int.parse(normalized.substring(0, 2));\n        final minute = int.parse(normalized.substring(3, 5));\n        final second = int.parse(normalized.substring(6, 8));\n        return DateTime(\n          backupDate.year,\n          backupDate.month,\n          backupDate.day,\n          hour,\n          minute,\n          second,\n        );\n      } catch (_) {\n        return null;\n      }\n    }\n\n    String fmt(DateTime dt) {\n      String pad(int n) => n.toString().padLeft(2, '0');\n      return '${pad(dt.hour)}:${pad(dt.minute)}';\n    }\n\n    final ini = parseUtcToLocal(hIniRaw);\n    final fin = parseUtcToLocal(hFinRaw);\n\n    if (ini != null && fin != null) return '${fmt(ini)} - ${fmt(fin)}';\n    if (ini != null) return fmt(ini);\n    if (fin != null) return fmt(fin);\n    return '';\n  }\n\n"""
if old not in text:
    raise SystemExit('original time helper not found')
text = text.replace(old, new)
path.write_text(text, encoding="utf-8")
